import {
  ArgumentMetadata,
  BadRequestException,
  PipeTransform,
} from '@nestjs/common';

/**
 * Coerces a query string to a TypeScript string-backed enum member value.
 *
 * Accepts either the enum wire value (RHS, e.g. ``pending``) or the DSL member
 * label (LHS key, e.g. ``Pending``), matching Python ``str, Enum`` query
 * behaviour and generated FastAPI routes.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
export class CoerceStringEnumPipe<
  T extends Record<string, string>,
> implements PipeTransform<string | undefined, T[keyof T] | undefined> {
  constructor(
    private readonly enumObject: T,
    private readonly optional: boolean,
  ) {}

  transform(
    value: string | undefined,
    _metadata: ArgumentMetadata,
  ): T[keyof T] | undefined {
    if (value === undefined || value === '') {
      if (this.optional) {
        return undefined;
      }
      throw new BadRequestException('Required query parameter is missing');
    }

    const values = Object.values(this.enumObject) as string[];
    if (values.includes(value)) {
      return value as T[keyof T];
    }

    const record = this.enumObject as Record<string, string>;
    if (Object.prototype.hasOwnProperty.call(record, value)) {
      const mapped = record[value];
      if (typeof mapped === 'string') {
        return mapped as T[keyof T];
      }
    }

    throw new BadRequestException(`Invalid enum value: ${String(value)}`);
  }
}
